import { CreateTaskInput, UpdateTaskInput, TaskResponse, TaskFilters, toTaskResponse } from '../models/task.js';
import { AppError } from './authService.js';

export interface PaginatedResult<T> {
  data: T[];
  total: number;
  page: number;
  limit: number;
  totalPages: number;
